import * as dgram from 'dgram';
import * as net from 'net';
import * as crypto from 'crypto';

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
}

interface DNSQuery {
  id: number;
  domain: string;
  type: number;
  source: { address: string; port: number };
}

interface AuthContext {
  negotiateFlags: number;
  challengeToken: Buffer;
  authenticated: boolean;
}

const CIRCUIT_THRESHOLD = 5;
const CIRCUIT_TIMEOUT = 30000;
const UPSTREAM_DNS = '10.0.0.53';
const AUTH_REQUIRED_ZONES = ['.internal.corp', '.auth.local'];

class NTLMAuthHandler {
  private sessions: Map<string, AuthContext> = new Map();

  createChallenge(clientId: string): Buffer {
    const challenge = crypto.randomBytes(8);
    this.sessions.set(clientId, {
      negotiateFlags: 0xe2088235,
      challengeToken: challenge,
      authenticated: false
    });
    return challenge;
  }

  validateResponse(clientId: string, response: Buffer): boolean {
    const session = this.sessions.get(clientId);
    if (!session) return false;

    const ntlmSignature = response.slice(0, 8).toString('ascii');
    const messageType = response.readUInt32LE(8);

    if (ntlmSignature !== 'NTLMSSP\0' || messageType !== 3) return false;

    const lmResponseLen = response.readUInt16LE(12);
    const ntResponseLen = response.readUInt16LE(20);

    if (lmResponseLen > 0 && ntResponseLen > 0) {
      session.authenticated = true;
      return true;
    }
    return false;
  }

  isAuthenticated(clientId: string): boolean {
    return this.sessions.get(clientId)?.authenticated ?? false;
  }

  shouldRequireAuth(domain: string): boolean {
    return AUTH_REQUIRED_ZONES.some(zone => domain.endsWith(zone));
  }
}

class CircuitBreaker {
  private circuits: Map<string, CircuitState> = new Map();

  getState(upstream: string): CircuitState {
    if (!this.circuits.has(upstream)) {
      this.circuits.set(upstream, { failures: 0, lastFailure: 0, state: 'CLOSED' });
    }
    return this.circuits.get(upstream)!;
  }

  recordFailure(upstream: string): void {
    const circuit = this.getState(upstream);
    circuit.failures++;
    circuit.lastFailure = Date.now();
    if (circuit.failures >= CIRCUIT_THRESHOLD) {
      circuit.state = 'OPEN';
    }
  }

  recordSuccess(upstream: string): void {
    const circuit = this.getState(upstream);
    circuit.failures = 0;
    circuit.state = 'CLOSED';
  }

  canRequest(upstream: string): boolean {
    const circuit = this.getState(upstream);
    if (circuit.state === 'CLOSED') return true;
    if (circuit.state === 'OPEN') {
      if (Date.now() - circuit.lastFailure > CIRCUIT_TIMEOUT) {
        circuit.state = 'HALF_OPEN';
        return true;
      }
      return false;
    }
    return true;
  }
}

class DNSResolver {
  private server: dgram.Socket;
  private circuitBreaker: CircuitBreaker;
  private authHandler: NTLMAuthHandler;
  private pendingQueries: Map<number, DNSQuery> = new Map();
  private fallbackUpstreams: string[] = ['10.0.0.54', '10.0.0.55'];

  constructor() {
    this.server = dgram.createSocket('udp4');
    this.circuitBreaker = new CircuitBreaker();
    this.authHandler = new NTLMAuthHandler();
  }

  start(port: number = 53): void {
    this.server.on('message', (msg, rinfo) => this.handleQuery(msg, rinfo));
    this.server.bind(port);
  }

  private handleQuery(msg: Buffer, rinfo: dgram.RemoteInfo): void {
    const query = this.parseDNSQuery(msg, rinfo);
    if (!query) return;

    const clientId = `${rinfo.address}:${rinfo.port}`;

    if (this.authHandler.shouldRequireAuth(query.domain)) {
      if (!this.authHandler.isAuthenticated(clientId)) {
        this.initiateNTLMAuth(clientId, query);
        return;
      }
    }

    this.resolveQuery(query);
  }

  private initiateNTLMAuth(clientId: string, query: DNSQuery): void {
    const challenge = this.authHandler.createChallenge(clientId);
    const responsePacket = this.buildAuthChallengeResponse(query.id, challenge);
    this.server.send(responsePacket, query.source.port, query.source.address);
  }

  private resolveQuery(query: DNSQuery): void {
    const upstream = this.selectUpstream();
    if (!upstream) {
      this.sendServFail(query);
      return;
    }

    this.pendingQueries.set(query.id, query);
    this.forwardToUpstream(query, upstream);
  }

  private selectUpstream(): string | null {
    if (this.circuitBreaker.canRequest(UPSTREAM_DNS)) {
      return UPSTREAM_DNS;
    }
    for (const fallback of this.fallbackUpstreams) {
      if (this.circuitBreaker.canRequest(fallback)) {
        return fallback;
      }
    }
    return null;
  }

  private forwardToUpstream(query: DNSQuery, upstream: string): void {
    const client = dgram.createSocket('udp4');
    const timeout = setTimeout(() => {
      this.circuitBreaker.recordFailure(upstream);
      client.close();
      this.handleUpstreamFailure(query, upstream);
    }, 5000);

    client.on('message', (response) => {
      clearTimeout(timeout);
      this.circuitBreaker.recordSuccess(upstream);
      this.relayResponse(query, response);
      client.close();
    });

    const packet = this.buildDNSPacket(query);
    client.send(packet, 53, upstream);
  }

  private handleUpstreamFailure(query: DNSQuery, failedUpstream: string): void {
    const nextUpstream = this.fallbackUpstreams.find(
      u => u !== failedUpstream && this.circuitBreaker.canRequest(u)
    );
    if (nextUpstream) {
      this.forwardToUpstream(query, nextUpstream);
    } else {
      this.sendServFail(query);
    }
  }

  private relayResponse(query: DNSQuery, response: Buffer): void {
    const modifiedResponse = Buffer.from(response);
    modifiedResponse.writeUInt16BE(query.id, 0);
    this.server.send(modifiedResponse, query.source.port, query.source.address);
  }

  private parseDNSQuery(msg: Buffer, rinfo: dgram.RemoteInfo): DNSQuery | null {
    if (msg.length < 12) return null;
    const id = msg.readUInt16BE(0);
    const flags = msg.readUInt16BE(2);
    if ((flags & 0x8000) !== 0) return null;

    let offset = 12;
    let domain = '';
    while (offset < msg.length) {
      const len = msg[offset];
      if (len === 0) { offset++; break; }
      if (offset + len + 1 > msg.length) return null;
      domain += (domain ? '.' : '') + msg.slice(offset + 1, offset + 1 + len).toString('ascii');
      offset += len + 1;
    }

    const type = offset + 1 < msg.length ? msg.readUInt16BE(offset) : 1;
    return { id, domain, type, source: { address: rinfo.address, port: rinfo.port } };
  }

  private buildAuthChallengeResponse(queryId: number, challenge: Buffer): Buffer {
    const response = Buffer.alloc(64);
    response.writeUInt16BE(queryId, 0);
    response.writeUInt16BE(0x8000, 2);
    challenge.copy(response, 12);
    return response;
  }

  private buildDNSPacket(query: DNSQuery): Buffer {
    const packet = Buffer.alloc(512);
    packet.writeUInt16BE(query.id, 0);
    packet.writeUInt16BE(0x0100, 2);
    packet.writeUInt16BE(1, 4);
    let offset = 12;
    const parts = query.domain.split('.');
    for (const part of parts) {
      packet[offset++] = part.length;
      packet.write(part, offset, 'ascii');
      offset += part.length;
    }
    packet[offset++] = 0;
    packet.writeUInt16BE(query.type, offset);
    packet.writeUInt16BE(1, offset + 2);
    return packet.slice(0, offset + 4);
  }

  private sendServFail(query: DNSQuery): void {
    const response = Buffer.alloc(12);
    response.writeUInt16BE(query.id, 0);
    response.writeUInt16BE(0x8002, 2);
    this.server.send(response, query.source.port, query.source.address);
  }
}

const resolver = new DNSResolver();
resolver.start(5353);
